insert into public.competitions (name, organiser, description, competition_type, domains, eligibility, student_only, prize_display, prize_max_inr, leads_to, typical_window, application_opens, application_closes, url, source_url, as_of_date) values
  ('Smart India Hackathon (SIH) 2026', 'Ministry of Education''s Innovation Cell and AICTE, Government of India', 'SIH is India''s largest national hackathon, now in its 9th edition (SIH 2026), where student teams solve real problem statements published by central ministries, state departments, PSUs and industry partners. It runs in two editions, software and hardware, with a 36-hour national grand finale hosted simultaneously at nodal centres across the country. SIH 2025 drew roughly 72,000 idea submissions from about 69,000 teams, of which 1,360 teams reached the national finale.', 'hackathon', '{"all"}', 'Teams of exactly 6 members including the team leader, with at least one female member, all enrolled in the same higher education institution in a regular full-time course. Teams must first win their college''s mandatory internal hackathon and be nominated by the institute''s SPOC.', true, '₹1.5 lakh per winning team, per problem statement (same for hardware and software editions)', 150000, 'Direct line to the ministry, PSU or company that owns the problem statement, which is the route to solution adoption, internships and follow-on support; national recognition that RVCE and other VTU colleges weight heavily.', 'SPOC / college registration around June-July; internal college hackathons and idea submission Aug-Sep; screening results Oct; grand finale in December', null, null, 'https://sih.gov.in/', 'https://sih.gov.in/faqs', '2026-08'),
  ('Hult Prize', 'Hult Prize Foundation', 'A global student startup competition in which teams launch a for-profit venture advancing at least one UN Sustainable Development Goal, running across 2,000+ campuses in 121 countries. It progresses through five rounds: campus/online qualifiers, nationals, a digital incubator, a global accelerator and the global finals. RV College of Engineering''s E-Cell runs a Hult Prize OnCampus round, which is the standard entry point for RVCE students.', 'competition', '{"all"}', 'Teams of 2-4 students, each at least 18 years old and currently enrolled in a degree-granting programme at any university. The venture must be for-profit and must address at least one UN SDG; non-profits are not eligible.', true, 'US$1,000,000 in seed funding for the global winning team', null, 'US$1M seed investment (the Hult Prize Foundation typically takes about a 10% equity stake), plus a digital incubator, a four-week global accelerator with mentoring and investor exposure, and a global founder network.', 'OnCampus qualifiers Nov-Feb; nationals Mar-May; digital incubator and global accelerator over the summer; global finals in September', null, null, 'https://www.hultprize.org/', 'https://www.hultprize.org/how-it-works', '2026-08'),
  ('Eureka!', 'Entrepreneurship Cell, IIT Bombay', 'Eureka! is E-Cell IIT Bombay''s flagship business model competition, billed as Asia''s largest, aimed at student teams and early-stage founders. Entries move through zonal rounds, a dedicated VC round and a grand finale, with structured mentorship in between. The 2026 edition advertises over ₹2 crore in prizes and benefits and more than ₹25 lakh in equity-free grants.', 'competition', '{"all"}', 'Open to student teams and early-stage founders from any institution in India and abroad; registration on the Eureka! portal is mandatory for every pitching team. Team size and stage requirements are set per edition and are not published as a fixed rule.', false, '₹2 crore+ in total prizes and benefits, including ₹25 lakh+ in equity-free grants', 20000000, 'Equity-free grant money, a dedicated round pitching to 45+ venture capital firms, mentorship from 300+ founders and investors, and follow-on fundraising conversations.', 'Registrations open in July; zonal rounds Sep-Oct; VC round in October; grand finale in December', '2026-07-10', '2026-08-18', 'https://www.ecell.in/eureka/', 'https://internshala.com/competitions/eureka-2026-by-iit-bombay-%E2%82%B92-crore/', '2026-08'),
  ('Empresario', 'Entrepreneurship Cell, IIT Kharagpur', 'Empresario is E-Cell IIT Kharagpur''s global business model competition for early-stage startups and student teams. Semi-finalists are assigned mentors drawn from operating founders and VC firms including Blume Ventures and Eximius Ventures, and finalists continue in a mentorship track through to the final pitch. Awards are given across Products & Services, Social Impact and Best IIT Kharagpur Entry.', 'competition', '{"all"}', 'Open to early-stage startups and student teams globally, entering in the Products & Services or Social Impact categories (plus a separate Best IIT Kharagpur Entry award). Team size and stage requirements are set per edition.', false, 'Prize pool of over ₹1.2 crore across categories, including incubation amounts', 12000000, 'Cash prizes and incubation amounts, sustained mentorship from VCs and operators for semi-finalists and finalists, and live pitching to angel investors, VCs and industrialists, with post-competition investment and networking follow-through.', null, null, null, 'https://www.ecell-iitkgp.org/empresario/', 'https://www.ecell-iitkgp.org/empresario/incentives/', '2026-08'),
  ('Conquest', 'BITS Pilani (student-run accelerator)', 'Conquest is a student-run, zero-cost zero-equity startup accelerator founded at BITS Pilani in 2004 and described as India''s largest non-diluting accelerator. It runs a roughly seven-week programme combining online mentorship with an offline week, and awards equity-free cash grants rather than taking a stake. The top shortlisted teams pitch to major investment firms in Bengaluru.', 'fellowship', '{"all"}', 'Open to early-stage startups from anywhere in India, including student-founded ventures. Applying is free: no fee, no equity and no hidden conditions.', false, 'Equity-free grants worth ₹10 lakh+ in the current edition; over ₹1 crore of non-dilutive grants disbursed in the last three years', 1000000, 'Equity-free cash grants, curated mentorship, investor connects, and a demo-day pitch in Bengaluru to leading VC and investment firms.', null, null, null, 'https://conquestbits.org/', 'https://conquestbits.org/process', '2026-08'),
  ('NSRCEL Campus Founders Programme', 'NSRCEL, IIM Bangalore', 'Campus Founders is NSRCEL''s incubation programme built specifically for student entrepreneurs who already have a working prototype. It runs in three phases: 6-10 weeks of virtual pre-incubation, 12-14 weeks of hybrid incubation, and up to six months of high-touch mentoring. It is one of the few Bengaluru-based programmes that puts non-dilutive money behind student ventures.', 'fellowship', '{"all"}', 'Undergraduate or postgraduate students, or graduates less than one year out, from any discipline anywhere in India. Applicants must have a working prototype and a scalable idea.', true, 'Milestone-based funding of up to ₹5 lakh for up to 5 promising ventures that reach Phase 3', 500000, 'Structured incubation at IIM Bangalore''s NSRCEL for up to about 10 months, milestone-based grant funding, and access to the NSRCEL mentor, corporate and investor network.', 'Applications are accepted through the NSRCEL application portal; cohort dates are not published as fixed deadlines', null, null, 'https://nsrcel.org/campus-founders/', 'https://nsrcel.org/campus-founders/', '2026-08'),
  ('ELEVATE (Startup Karnataka)', 'Karnataka Innovation and Technology Society (KITS), Department of Electronics, IT, BT and S&T, Government of Karnataka', 'ELEVATE is the Karnataka government''s flagship grant-in-aid scheme for early-stage startups, offering a one-time non-dilutive grant to build prototypes, validate proof of concept and scale. The 25th call in 2026 ran four simultaneous tracks for the first time: the general ELEVATE call, Shakti for women-led startups, Unnati for SC/ST founders and Aspire for startups registered outside Bengaluru Urban. Funds are released in two equal tranches, the first after a tripartite agreement and the second after a milestone review.', 'challenge', '{"all"}', 'Registered early-stage startup entities based in Karnataka; entity age, turnover and funding criteria are specified per call. Student founders need an incorporated entity to apply, so this is the natural next step after a college-level or NAIN-funded prototype.', false, 'One-time grant-in-aid of up to ₹50 lakh, fully non-dilutive (no equity taken)', 5000000, 'Up to ₹50 lakh of non-dilutive government funding released against milestones, plus incubation support and formal recognition inside the Startup Karnataka ecosystem.', 'Calls open roughly annually; the 25th call ran 25 May to 25 June 2026 (that window has closed)', '2026-05-25', '2026-06-25', 'https://elevate.startupkarnataka.in/', 'https://www.startupgrantsindia.com/elevate-2026-startup-karnataka-grant-in-aid', '2026-08'),
  ('New Age Innovation Network (NAIN) Student Project Funding', 'Karnataka Innovation and Technology Society (KITS), Government of Karnataka', 'NAIN is Karnataka''s scheme for funding student-led innovation directly on campus, run through NAIN centres hosted at universities and colleges across the state. It exists to let students, research scholars and alumni take a local problem from idea to validated proof of concept with government seed money. Karnataka has stated it plans to open 50 new NAIN centres by 2027.', 'challenge', '{"all"}', 'Students, research scholars and alumni of institutions that host a NAIN centre in Karnataka. Teams apply through their host institution''s NAIN or innovation cell, not through a central portal.', true, 'Seed fund of up to ₹3 lakh per selected project, with up to 10 teams funded per host institution', 300000, 'Non-dilutive seed funding plus incubation support at the host NAIN centre to reach proof of concept, and a documented on-ramp into the wider Startup Karnataka funding ladder such as ELEVATE.', 'Selection cycles are run by each host NAIN centre; there is no single statewide date', null, null, 'https://startup.karnataka.gov.in/new-age-innovation-network/', 'https://startup.karnataka.gov.in/new-age-innovation-network/', '2026-08'),
  ('e-Yantra Robotics Competition (eYRC)', 'e-Yantra, IIT Bombay (funded by the Ministry of Education)', 'eYRC is IIT Bombay''s annual project-based robotics competition, structured as a hardware-based MOOC in which teams work through staged tasks over roughly six months. Themes cover embedded systems, robotics, AI/ML, control systems and image processing, and teams that clear Stage 1 receive free robotics kits. Registrations grew from 4,500 teams in 2012 to about 34,500 entries in India, and the 2026-27 edition is live.', 'competition', '{"hardware","ai_ml","deeptech"}', 'Teams of full-time students at a polytechnic, engineering college or university; international teams are also accepted. Only basic programming knowledge is assumed as training is provided. A registration fee applies (₹3,000 per Indian student team in recent editions).', true, 'Cash prizes for national finalists (amount not published on official e-Yantra pages), plus 8-week paid internships at IIT Bombay', null, 'Paid 8-week summer internships at IIT Bombay through the e-Yantra Summer Internship Programme (eYSIP), IIT Bombay certificates, and free hardware kits plus deep embedded/robotics training that functions as a strong hiring signal.', 'Registrations Aug-Sep; online staged tasks Nov-Feb; national finals in person at IIT Bombay in March', null, null, 'https://www.e-yantra.org/eyrc', 'https://www.iitb.ac.in/launch-e-yantra-robotics-competition-register-now', '2026-08'),
  ('Google Solution Challenge', 'Google (Google Developer Groups on Campus)', 'The Solution Challenge asks university student teams to build a solution to one or more of the UN''s 17 Sustainable Development Goals using Google technologies. Judges shortlist a Top 100, who get direct mentorship from Google engineers and Google Developer Experts before resubmitting, then a Top 10 who present at a global Demo Day. India additionally runs its own GDG on Campus India Solution Challenge track with a separate rupee prize pool.', 'challenge', '{"all"}', 'University students worldwide, participating through a Google Developer Group on Campus chapter. Teams build and submit a working solution using Google technologies that addresses at least one UN SDG.', true, 'Global: US$3,000 per team member for the top 3 teams, US$1,000 per member for the rest of the top 10. India track: ₹10 lakh prize pool with a ₹4 lakh first prize, ₹3 lakh second, ₹2 lakh third and two ₹50,000 special category awards.', 400000, 'Customised mentorship from Google and Google Developer Experts for the Top 100, a feature on the Google Developers Blog, exposure on the global Demo Day livestream, and official Google certificates at prototype, Top 100, Top 10 and winner stages.', 'Launches early March; submissions close end of June; Top 100 and Top 10 announced through the summer, with Demo Day and winners after that', '2026-03-06', '2026-06-30', 'https://developers.google.com/community/gdsc-solution-challenge', 'https://gdg.community.dev/events/details/google-gdg-on-campus-indian-institute-of-technology-bhilai-india-presents-gdg-on-campus-india-solution-challenge-2026-build-with-ai/', '2026-08'),
  ('Samsung Solve for Tomorrow India', 'Samsung India (CSR), with FITT, IIT Delhi as incubation partner', 'Solve for Tomorrow is Samsung India''s national innovation competition for young people, now in its fifth year, asking entrants to build tech-driven solutions to real social problems. Support scales with progress: prototype money for the top 40 and top 20, a bootcamp, and a grand finale where four winning teams share a ₹2 crore grant. Winners are incubated at FITT, IIT Delhi to make their prototype market-ready.', 'challenge', '{"all"}', 'Indian residents aged 14 to 22 (as of 30 June 2026), applying individually or in teams of up to three, with an original science or technology idea or product with social impact. Eligibility is age-based rather than enrolment-based.', false, '₹2 crore total grant shared by the 4 winning teams; ₹1 lakh each for the top 20 and ₹20,000 each for the top 40; plus two Community Choice Awards (₹1 lakh each) and a ₹50,000 Digital Impact Award', 20000000, 'Incubation support at FITT, IIT Delhi to take the prototype to market, staged prototype funding at top-40 and top-20 stages, and mentorship from Samsung and industry experts.', 'Applications roughly Feb to end-June; online training in July; bootcamp in September; grand finale in October', null, '2026-06-30', 'https://www.samsung.com/in/solvefortomorrow/', 'https://www.samsung.com/in/solvefortomorrow/', '2026-08'),
  ('Microsoft Imagine Cup', 'Microsoft', 'Imagine Cup is Microsoft''s global student startup competition, in which student founders build a startup on Microsoft Azure and AI technologies and progress through regional finals to a world championship announced at Microsoft Build. The 2026 world championship was won in June 2026 by CopyFlag, an AI platform that detects copied designs online and triggers corrective action. Teams get Azure credits and Microsoft coaching along the way.', 'competition', '{"ai_ml","saas","deeptech"}', 'Student founders enrolled at an accredited academic institution, competing in small teams, building a startup on Microsoft technologies. Exact age and team-size limits are set in each year''s official rules.', true, 'US$150,000 grand prize plus a mentorship session with Microsoft CEO Satya Nadella; up to US$15,000 for first place in each regional final', null, 'Up to US$5,000 in Azure credits to build and test the MVP, coaching from Microsoft experts, connections into Microsoft''s startup programmes, and exposure to the global tech and investor community.', 'Registrations open in the autumn; regional finals in spring; world championship winner announced at Microsoft Build in late May/early June', null, null, 'https://imaginecup.microsoft.com/', 'https://news.microsoft.com/signal/articles/imagine-cup-2026-student-ai-competition/', '2026-08'),
  ('Y Combinator Startup School', 'Y Combinator', 'Startup School is YC''s free, open online programme on how to start a startup, with no application, no fee and no equity taken. It includes 30+ video lectures from YC partners and founders, plus an Aspiring Founders track that is a structured free six-week course across eight modules with weekly live group video sessions. It runs continuously, with scheduled cohorts several times a year.', 'fellowship', '{"all"}', 'Open to anyone worldwide, including students still in college. No application process, no cost and no equity; sign up directly at startupschool.org.', false, 'No prize money — free programme, no equity taken', null, 'Structured founder curriculum, weekly small-group sessions with other founders, co-founder matching, and a direct on-ramp to applying to the Y Combinator accelerator.', 'Runs continuously; scheduled cohorts kick off several times a year (2026 cohorts listed for January, April, July and October)', null, null, 'https://www.startupschool.org/', 'https://www.startupschool.org/aspiring-founders', '2026-08'),
  ('Atal New India Challenge (ANIC 2.0)', 'Atal Innovation Mission, NITI Aayog', 'ANIC is Atal Innovation Mission''s productisation and commercialisation challenge, taking prototype-stage technology innovations through to market over 12-18 months with grant-in-aid of up to ₹1 crore. ANIC 2.0 published 18 challenges across seven sectors in Phase 1, including e-mobility, road transportation, space technology, sanitation, medical devices, waste management and agriculture. Note: no new ANIC application window is published as of August 2026 and the ANIC 2.0 pages carry a last-updated date of January 2024, so treat this as dormant until AIM announces a fresh call.', 'challenge', '{"healthtech","climate","agritech","spacetech","logistics","deeptech"}', 'Indian startups, companies and innovators with a working prototype addressing one of the published sectoral challenges. Detailed criteria are published per challenge on the AIM portal.', false, 'Grant-in-aid of up to ₹1 crore per selected innovation', 10000000, 'Up to ₹1 crore of productisation and commercialisation funding over 12-18 months, plus mentorship, networking and incubation support from Atal Incubation Centres across the country.', null, null, null, 'https://aim.gov.in/atal-new-india-challenge-2.0.php', 'https://aim.gov.in/anic-overview.php', '2026-08'),
  ('Youth Co:Lab National Innovation Challenge', 'Atal Innovation Mission (NITI Aayog) and UNDP India, with T-Hub Foundation', 'Youth Co:Lab is the AIM-UNDP national innovation challenge for youth-led startups, running its eighth edition in 2026 on the theme of Responsible Consumption, aligned to Mission LiFE. Sub-themes are sustainable textiles and fashion, circular economy innovations, and sustainable food systems and water conservation. Up to 50 startups join a virtual Springboard programme, the top 20 attend a five-day immersion at T-Hub Hyderabad, and the top 6 receive seed grants.', 'challenge', '{"climate","agritech","consumer"}', 'Youth-led startups whose founders are aged 15-29, extended to 35 for women, persons with disabilities, LGBTIQA+ founders, tribal entrepreneurs and founders from minority communities. The solution must address one of the year''s published sub-themes.', false, 'Seed grants of ₹2.2 lakh to ₹3.5 lakh each for the top 6 startups', 350000, 'Virtual mentorship and capacity building for up to 50 startups, a five-day immersion bootcamp at T-Hub Hyderabad for the top 20, seed grants for the top 6, and continued mentor and investor connections with national visibility.', 'Applications open early in the calendar year and close in March; training, National Innovation Dialogue and immersion follow, with awards later in the year', null, '2026-03-20', 'https://aim.gov.in/youthcolab.php', 'https://aim.gov.in/youthcolab.php', '2026-08'),
  ('Biotechnology Ignition Grant (BIG)', 'Biotechnology Industry Research Assistance Council (BIRAC), Department of Biotechnology, Government of India', 'BIG is India''s largest early-stage biotech grant, giving up to ₹50 lakh of grant-in-aid over 18 months to turn an idea into a validated proof of concept. It is explicitly open to scientist-entrepreneurs from academia and research institutes as well as young startups, so a student with a translational biotech idea can apply directly. Grantees also get mentoring and business development support through BIRAC''s network of BIG Partner incubators.', 'challenge', '{"healthtech","deeptech","agritech"}', 'Indian nationals (not OCI/PIO): scientist-entrepreneurs from research institutes and academia, students, and early-stage startups. Student applicants must obtain a No Objection Certificate from their institute.', false, 'Grant-in-aid of up to ₹50 lakh for 18 months', 5000000, 'Non-dilutive proof-of-concept funding, plus mentoring, monitoring, networking and business development support delivered through BIRAC''s partner incubators, and a track record that unlocks BIRAC''s later-stage schemes.', 'Calls are announced twice a year, on 1 January and 1 July, and stay open for roughly 45 days', null, null, 'https://birac.nic.in/big.php', 'https://birac.nic.in/big.php', '2026-08'),
  ('NIDHI PRAYAS 2.0', 'Department of Science and Technology (DST), Government of India, delivered through PRAYAS Centres at host incubators', 'NIDHI PRAYAS funds young innovators to convert a science or technology idea into a working physical prototype, and is one of the few Indian schemes that gives money to an individual innovator rather than requiring an incorporated company. Under PRAYAS 2.0, innovators can receive up to ₹20 lakh through a PRAYAS Centre, or up to ₹40 lakh through an Advance PRAYAS Centre for deep-tech or advanced prototypes. Applications are made to a designated PRAYAS Centre, several of which operate in Karnataka.', 'challenge', '{"deeptech","hardware","climate","healthtech"}', 'Individual innovators aged 18 or over without a company, or founders of an early-stage startup, applying through a DST-recognised PRAYAS Centre. Students pursuing long-term doctoral or similar research projects are not supported.', false, 'Up to ₹20 lakh per innovator via a PRAYAS Centre; up to ₹40 lakh via an Advance PRAYAS Centre for deep-tech or advanced prototypes', 4000000, 'Non-dilutive prototype funding, fabrication and lab access plus incubation at the host PRAYAS Centre, and a documented route into the wider DST NIDHI funding chain.', 'Innovator calls are run by individual PRAYAS Centres throughout the year; DST''s own call for host incubators to become PRAYAS Centres ran 19 May to 30 June 2026', null, null, 'https://nidhi-prayas.org/', 'https://nidhi.dst.gov.in/schemes-programmes/nidhiprayas/', '2026-08'),
  ('iDEX Defence India Startup Challenge / Open Challenge', 'Innovations for Defence Excellence (iDEX), Defence Innovation Organisation, Ministry of Defence', 'iDEX runs the Defence India Startup Challenge (DISC) rounds plus a rolling Open Challenge, funding Indian innovators to prototype solutions for problem statements raised by the Army, Navy, Air Force and Coast Guard. DISC 14 alone released 82 problem statements spanning AI, autonomous systems, drone warfare, electronic intelligence, cybersecurity and advanced materials. Selected innovators receive milestone-linked grant funding of up to ₹1.5 crore.', 'challenge', '{"defence","deeptech","ai_ml","hardware","spacetech"}', 'Indian startups, MSMEs, R&D institutes and individual innovators with a technology solution to a published defence problem statement. Not student-restricted, so a student venture must be able to execute against a defence-grade prototype milestone plan.', false, 'Grant of up to ₹1.5 crore per selected innovator', 15000000, 'Up to ₹1.5 crore of milestone-linked prototype funding, a serving-forces mentor and access to trial facilities, and a realistic path to a procurement order from the armed forces.', 'DISC and ADITI rounds are announced periodically through the year; the iDEX Open Challenge runs on a rolling basis (the current Open Challenge closes 30 September 2026)', null, '2026-09-30', 'https://idex.gov.in/challenges', 'https://idex.gov.in/challenges', '2026-08')
