-- Competition calendar: student-accessible contests with a real outcome —
-- prize money, incubation or a funding fast-track. 18 rows, each sourced.

on conflict (name) do update set organiser = excluded.organiser, description = excluded.description, competition_type = excluded.competition_type, domains = excluded.domains, eligibility = excluded.eligibility, student_only = excluded.student_only, prize_display = excluded.prize_display, prize_max_inr = excluded.prize_max_inr, leads_to = excluded.leads_to, typical_window = excluded.typical_window, application_opens = excluded.application_opens, application_closes = excluded.application_closes, url = excluded.url, source_url = excluded.source_url, as_of_date = excluded.as_of_date;
